    java.util.HashSet dn = new java.util.HashSet();
    for (int i = 0; i < del.length(); i++) dn.add(del.getString(i));
    java.util.HashSet pg = new java.util.HashSet();
    for (int i = 0; i < macs.length(); i++) pg.add(String.valueOf(macs.getJSONObject(i).optLong("m_GUID")));
    JSONArray all = new JSONArray();
    int gone = 0;
    for (int i = 0; i < cur0.length(); i++) {
