      if (dn.contains(m0.optString("m_name"))) { gone++; continue; }
      if (pg.contains(String.valueOf(m0.optLong("m_GUID")))) continue;
      all.put(m0);
    }
    for (int i = 0; i < macs.length(); i++) all.put(macs.getJSONObject(i));
