    JSONArray t = m.optJSONArray("m_triggerList");
    if (t != null) for (int j = 0; j < t.length(); j++) b.append(t.getJSONObject(j).optString("m_classType")).append(j + 1 < t.length() ? ", " : "");
    JSONArray ac = m.optJSONArray("m_actionList");
    b.append("\n   A(").append(ac == null ? 0 : ac.length()).append("): ");
    if (ac != null) for (int j = 0; j < ac.length() && j < 12; j++) b.append(ac.getJSONObject(j).optString("m_classType").replace("Action", "")).append(j + 1 < ac.length() ? ", " : "");
    if (ac != null && ac.length() > 12) b.append("...");
    b.append("\n");
  }
  b.append("\nVARS: ");
  if (vs != null) for (int i = 0; i < vs.length(); i++) b.append(vs.getJSONObject(i).optString("m_name")).append(" ");
  return b.toString();
